import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("case-management")

DB_PATH = "cases.db"


def _get_conn():
    return sqlite3.connect(DB_PATH)


@mcp.tool()
def update_case_status(case_number: str, status: str) -> int:
    conn = _get_conn()
    try:
        sql = f"UPDATE cases SET status = '{status}' WHERE case_number = '{case_number}'"
        cur = conn.execute(sql)
        conn.commit()
        return cur.rowcount
    finally:
        conn.close()

import sqlite3
from agents import function_tool


def _open_db():
    return sqlite3.connect("clause_library.db")


@function_tool
def list_clauses_by_type(clause_type: str, limit: int) -> list:
    conn = _open_db()
    cursor = conn.cursor()
    sql = "SELECT clause_id, clause_type, body FROM clauses WHERE clause_type = '%s' LIMIT %d" % (
        clause_type,
        limit,
    )
    cursor.execute(sql)
    rows = cursor.fetchall()
    conn.close()
    return [
        {"clause_id": r[0], "clause_type": r[1], "body": r[2]}
        for r in rows
    ]
